      {"op": "eq", "left": {"var": "active_deployment", "when": "after"}, "right": {"var": "allocated_resources", "when": "before"}},
      {"op": "eq", "left": {"var": "allocated_resources", "when": "after"}, "right": {"op": "union", "left": {"var": "allocated_resources", "when": "before"}, "right": {"const": {"cpu": 1, "ram": 1}}}},
      {"op": "eq", "left": {"var": "available_quota", "when": "after"}, "right": {"op": "difference", "left": {"var": "available_quota", "when": "before"}, "right": {"const": {"cpu": 1, "ram": 1}}}},
      {"op": "unchanged", "vars": ["authenticated", "target_region", "cluster_tier"]}
    ]
  }
}

